module optimize_friends (\n    input clk,\n    input rst_n,\n    input start,\n    input [2:0] n,\n    input [15:0] p0, p1, p2, p3, p4, p5, p6, p7,\n    output reg [31:0] result,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE    = 3'b000;\n    localparam [2:0] CHECK   = 3'b001;\n    localparam [2:0] SORT    = 3'b010;\n    localparam [2:0] INIT    = 3'b011;\n    localparam [2:0] LOOP    = 3'b100;\n    localparam [2:0] DONE_ST = 3'b101;\n\n    reg [2:0] state;\n    reg [31:0] prob [0:7];\n    wire [31:0] one = 32'hFFFFFFFF;\n    reg [31:0] s, p, a;\n    reg [2:0] i, j, k;\n    reg [7:0] cycle_count;\n    localparam [7:0] MAX_CYCLES = 8'd100;\n\n    // Multiplier outputs\n    wire [63:0] product1 = s * (one - a);\n    wire [63:0] product2 = a * p;\n    wire [63:0] product3 = p * (one - a);\n\n    integer idx;  // For loop index\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 32'd0;\n            s <= 32'd0;\n            p <= 32'd0;\n            a <= 32'd0;\n            i <= 3'd0;\n            j <= 3'd0;\n            k <= 3'd0;\n            cycle_count <= 8'd0;\n            for (idx = 0; idx < 8; idx = idx + 1) begin\n                prob[idx] <= 32'd0;\n            end\n        end else begin\n            cycle_count <= (state == IDLE) ? 8'd0 : cycle_count + 8'd1;\n\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start && (cycle_count < MAX_CYCLES)) begin\n                        state <= CHECK;\n                        prob[0] <= {p0, 16'b0};\n                        prob[1] <= {p1, 16'b0};\n                        prob[2] <= {p2, 16'b0};\n                        prob[3] <= {p3, 16'b0};\n                        prob[4] <= {p4, 16'b0};\n                        prob[5] <= {p5, 16'b0};\n                        prob[6] <= {p6, 16'b0};\n                        prob[7] <= {p7, 16'b0};\n                    end\n                end\n\n                CHECK: begin\n                    if (p0 == 16'hFFFF || p1 == 16'hFFFF || p2 == 16'hFFFF || p3 == 16'hFFFF ||\n                        p4 == 16'hFFFF || p5 == 16'hFFFF || p6 == 16'hFFFF || p7 == 16'hFFFF) begin\n                        result <= 32'hFFFFFFFF;\n                        done <= 1'b1;\n                        state <= IDLE;\n                    end else begin\n                        state <= SORT;\n                        j <= 3'd0;\n                        k <= 3'd0;\n                    end\n                end\n\n                SORT: begin\n                    if (j < n && (cycle_count < MAX_CYCLES)) begin\n                        if (k < n - 3'd1 - j) begin\n                            if (prob[k] < prob[k+3'd1]) begin\n                                prob[k] <= prob[k+3'd1];\n                                prob[k+3'd1] <= prob[k];\n                            end\n                            k <= k + 3'd1;\n                        end else begin\n                            k <= 3'd0;\n                            j <= j + 3'd1;\n                        end\n                    end else begin\n                        state <= INIT;\n                        i <= n - 3'd2;\n                    end\n                end\n\n                INIT: begin\n                    s <= prob[n-3'd1];\n                    p <= one - prob[n-3'd1];\n                    state <= LOOP;\n                end\n\n                LOOP: begin\n                    if (i >= 3'd0 && (cycle_count < MAX_CYCLES)) begin\n                        a <= prob[i];\n                        if ((product1 + product2) > {s, 32'd0}) begin\n                            s <= (product1 + product2) >> 32;\n                            p <= product3 >> 32;\n                        end\n                        i <= i - 3'd1;\n                    end else begin\n                        state <= DONE_ST;\n                        result <= s;\n                        done <= 1'b1;\n                    end\n                end\n\n                DONE_ST: begin\n                    state <= IDLE;\n                    done <= 1'b0;\n                end\n\n                default: state <= IDLE;\n            endcase\n\n            // Timeout safety\n            if (cycle_count >= MAX_CYCLES) begin\n                state <= IDLE;\n                done <= 1'b0;\n            end\n        end\n    end\n\nendmodule